if __name__ == "__main__":
    ciphertext = " 1"
    key = "636f6d7075746572656e6e65747765726b7365637572697479697374686562657374636f75727365"

    c_bin = bytes.fromhex(ciphertext.replace(" ", ""))
    k_bin = bytes.fromhex(key)


    plaintext = []
    for i in range(len(c_bin)):
        c_byte = c_bin[i]
        k_byte = k_bin[i % len(k_bin)]
        plaintext.append(c_byte ^ k_byte)

    plaintext_hex = bytes(plaintext)
    plaintext_bin = bytes.fromhex(plaintext_hex)
    print(plaintext_bin.decode("ascii"))


